const record =
  $json.document_record;

const isValidRecord =
  record !== null
  && typeof record === 'object'
  && !Array.isArray(record)
  && Object.keys(record).length > 0
  && Boolean(
    record.id
    || record.external_document_id
    || record.file_name
    || record.raw_json
  );

if (!isValidRecord) {
  return {
    json: {
      opportunity_analysis_id:
        $json.opportunity_analysis_id ?? null,

      organization_id:
        $json.organization_id ?? null,

      process_id:
        $json.process_id ?? null,

      process_reference:
        $json.process_reference ?? '',

      process_name:
        $json.process_name ?? '',

      has_process_document:
        false,

      document_name:
        '',

      document_type:
        '',

      file_extension:
        '',

      download_url:
        null,

      download_url_text:
        '',

      detected_categories:
        [],

      relevant_for_analysis:
        false,

      empty_document_result:
        true,

      classification_message:
        'El proceso seleccionado no tiene documentos vinculados en secop.process_documents.',

      document_record:
        {},
    },
  };
}

const firstValue = (...keys) => {
  for (const key of keys) {
    const value = record[key];

    if (
      value !== null
      && value !== undefined
      && String(value).trim() !== ''
    ) {
      return value;
    }
  }

  return null;
};

const normalizeText = (value) =>
  String(value ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();

const documentName =
  String(
    firstValue(
      'file_name',
      'document_name',
      'name',
      'title',
      'titulo',
      'nombre_documento',
      'filename'
    ) ?? ''
  ).trim();

const fileExtension =
  String(
    firstValue(
      'file_extension',
      'extension',
      'extensi_n'
    ) ?? ''
  )
    .replace(/^\./, '')
    .trim()
    .toLowerCase();

const documentType =
  String(
    firstValue(
      'document_type',
      'type',
      'tipo_documento',
      'document_category'
    ) ?? ''
  ).trim();

const rawDownloadUrl =
  firstValue(
    'download_url',
    'url',
    'file_url',
    'document_url',
    'storage_url'
  );

let downloadUrlText = '';

if (typeof rawDownloadUrl === 'string') {
  downloadUrlText =
    rawDownloadUrl.trim();
} else if (
  rawDownloadUrl
  && typeof rawDownloadUrl === 'object'
) {
  downloadUrlText =
    String(
      rawDownloadUrl.url
      ?? rawDownloadUrl.href
      ?? rawDownloadUrl.download
      ?? ''
    ).trim();
}

if (!downloadUrlText) {
  downloadUrlText =
    String(
      record.download_url_text
      ?? record.raw_json
          ?.url_descarga_documento
          ?.url
      ?? ''
    ).trim();
}

const searchableText =
  normalizeText(
    [
      documentName,
      record.description,
      record.raw_json?.nombre_archivo,
      record.raw_json?.descripci_n,
    ].join(' ')
  );

const categories = [];

const addCategory = (
  category,
  keywords
) => {
  if (
    keywords.some(
      (keyword) =>
        searchableText.includes(keyword)
    )
  ) {
    categories.push(category);
  }
};

addCategory(
  'invitation_or_terms',
  [
    'invitacion',
    'pliego',
    'terminos',
    'condiciones',
  ]
);

addCategory(
  'previous_studies',
  [
    'estudio previo',
    'estudios previos',
  ]
);

addCategory(
  'technical_annex',
  [
    'anexo tecnico',
    'ficha tecnica',
    'especificaciones tecnicas',
  ]
);

addCategory(
  'economic_offer_template',
  [
    'oferta economica',
    'propuesta economica',
    'formato economico',
  ]
);

addCategory(
  'entity_template',
  [
    'formato',
    'carta de presentacion',
    'declaracion',
    'manifestacion',
    'compromiso',
  ]
);

addCategory(
  'addendum',
  [
    'adenda',
    'modificacion',
  ]
);

addCategory(
  'risk_matrix',
  [
    'matriz de riesgos',
    'matriz de riesgo',
  ]
);

const uniqueCategories =
  [...new Set(categories)];

const relevantForAnalysis =
  uniqueCategories.length > 0;

const supportedExtensions =
  new Set([
    'pdf',
    'doc',
    'docx',
    'xls',
    'xlsx',
    'odt',
    'ods',
  ]);

const hasDownloadUrl =
  Boolean(downloadUrlText);

const supportedFile =
  supportedExtensions.has(
    fileExtension
  );

return {
  json: {
    opportunity_analysis_id:
      $json.opportunity_analysis_id,

    organization_id:
      $json.organization_id,

    process_id:
      $json.process_id,

    process_reference:
      $json.process_reference,

    process_name:
      $json.process_name,

    has_process_document:
      true,

    process_document_id:
      record.id ?? null,

    external_document_id:
      record.external_document_id ?? null,

    document_name:
      documentName,

    document_type:
      documentType,

    file_extension:
      fileExtension,

    description:
      String(
        record.description ?? ''
      ),

    download_url:
      rawDownloadUrl ?? null,

    download_url_text:
      downloadUrlText,

    detected_categories:
      uniqueCategories,

    primary_category:
      uniqueCategories[0]
      ?? 'other',

    relevant_for_analysis:
      relevantForAnalysis,

    has_download_url:
      hasDownloadUrl,

    supported_file:
      supportedFile,

    download_candidate:
      hasDownloadUrl
      && supportedFile
      && relevantForAnalysis,

    needs_manual_review:
      !relevantForAnalysis,

    empty_document_result:
      false,

    classified_at:
      new Date().toISOString(),

    document_record:
      record,
  },
};

const binaryData = $binary ?? {};
const downloadedFile = binaryData.data ?? null;

const downloadSuccess =
  downloadedFile !== null
  && typeof downloadedFile === 'object';

let errorMessage = null;

if (!downloadSuccess) {
  const possibleError =
    $json.error
    ?? $json.message
    ?? $json.statusMessage
    ?? $json.cause
    ?? null;

  if (possibleError !== null) {
    errorMessage =
      typeof possibleError === 'object'
        ? JSON.stringify(possibleError)
        : String(possibleError);
  } else {
    errorMessage =
      'El servidor no devolvió un archivo binario.';
  }
}

return {
  json: {
    ...$json,

    download_success:
      downloadSuccess,

    download_status:
      downloadSuccess
        ? 'downloaded'
        : 'failed',

    downloaded_filename:
      downloadSuccess
        ? String(
            downloadedFile.fileName
            ?? $json.document_name
            ?? 'documento'
          )
        : null,

    downloaded_mime_type:
      downloadSuccess
        ? String(
            downloadedFile.mimeType
            ?? ''
          )
        : null,

    downloaded_file_extension:
      downloadSuccess
        ? String(
            downloadedFile.fileExtension
            ?? $json.file_extension
            ?? ''
          )
        : null,

    downloaded_file_size:
      downloadSuccess
        ? (
            downloadedFile.fileSize
            ?? null
          )
        : null,

    download_error:
      errorMessage,

    downloaded_at:
      new Date().toISOString(),
  },

  binary:
    binaryData,
};

const parseFileSize = (value) => {
  if (
    typeof value === 'number'
    && Number.isFinite(value)
    && value > 0
  ) {
    return Math.round(value);
  }

  const text = String(value ?? '')
    .trim()
    .toLowerCase();

  if (!text) {
    return null;
  }

  const match = text.match(
    /^([\d.,]+)\s*(b|kb|kib|mb|mib|gb|gib)?$/i
  );

  if (!match) {
    return null;
  }

  const normalizedAmount = match[1]
    .replace(/\s/g, '')
    .replace(',', '.');

  const amount = Number(normalizedAmount);

  if (
    !Number.isFinite(amount)
    || amount <= 0
  ) {
    return null;
  }

  const unit = String(
    match[2] ?? 'b'
  ).toLowerCase();

  const multipliers = {
    b: 1,
    kb: 1000,
    kib: 1024,
    mb: 1000 ** 2,
    mib: 1024 ** 2,
    gb: 1000 ** 3,
    gib: 1024 ** 3,
  };

  return Math.round(
    amount * (multipliers[unit] ?? 1)
  );
};


// Archivo binario descargado
const binaryData = $binary ?? {};
const downloadedFile = binaryData.data ?? null;


// Primera opción: tamaño calculado por el nodo de validación
const sizeFromValidation = parseFileSize(
  $json.downloaded_file_size
);


// Segunda opción: tamaño almacenado en el binario
const sizeFromBinary = parseFileSize(
  downloadedFile?.fileSize
);


// Tercera opción: tamaño informado por SECOP
const rawSourceSize = Number(
  $json.document_record?.file_size_bytes
  ?? 0
);

const sizeFromSource =
  Number.isFinite(rawSourceSize)
  && rawSourceSize > 0
    ? Math.round(rawSourceSize)
    : null;


// Se toma el primer tamaño válido disponible
const downloadedFileSizeBytes =
  sizeFromValidation
  ?? sizeFromBinary
  ?? sizeFromSource
  ?? null;


// Hash calculado por el nodo Crypto
const downloadSha256 = String(
  $json.download_sha256
  ?? $json.hash
  ?? ''
).trim().toLowerCase();


// Metadatos para auditoría
const registrationMetadata = {
  workflow_code:
    'WF-013',

  n8n_execution_id:
    String($execution.id ?? ''),

  process_reference:
    $json.process_reference
    ?? null,

  process_document_id:
    $json.process_document_id
    ?? null,

  external_document_id:
    $json.external_document_id
    ?? null,

  source_download_url:
    $json.download_url_text
    ?? null,

  classified_at:
    $json.classified_at
    ?? null,

  selected_at:
    $json.selected_at
    ?? null,

  downloaded_at:
    $json.downloaded_at
    ?? new Date().toISOString(),

  registered_at:
    new Date().toISOString(),
};


return {
  json: {
    ...$json,

    download_sha256:
      downloadSha256 || null,

    downloaded_file_size_bytes:
      downloadedFileSizeBytes,

    downloaded_mime_type:
      String(
        $json.downloaded_mime_type
        ?? downloadedFile?.mimeType
        ?? ''
      ).trim() || null,

    downloaded_file_extension:
      String(
        $json.downloaded_file_extension
        ?? downloadedFile?.fileExtension
        ?? $json.file_extension
        ?? ''
      )
        .trim()
        .toLowerCase()
        || null,

    downloaded_filename:
      String(
        $json.downloaded_filename
        ?? downloadedFile?.fileName
        ?? $json.document_name
        ?? 'documento'
      ).trim(),

    registration_metadata:
      registrationMetadata,

    prepared_for_registration_at:
      new Date().toISOString(),
  },

  binary:
    binaryData,
};

const items =
  $input.all();

const opportunityIds =
  [
    ...new Set(
      items
        .map(
          (item) =>
            item.json
              .opportunity_analysis_id
        )
        .filter(Boolean)
    )
  ];

return [
  {
    json: {
      opportunity_analysis_ids:
        opportunityIds,

      opportunity_analysis_ids_json:
        JSON.stringify(
          opportunityIds
        ),

      processed_download_results:
        items.length,

      prepared_at:
        new Date().toISOString(),
    },
  },
];
